/**
 * `pnpm db:setup`: create the trust-zone login roles, apply migrations and seed the
 * dev tenants. Reads packages/db/.env (generated by scripts/gen-local-env.mjs).
 */
import { existsSync } from 'node:fs';
import { devTenants, setupDatabase } from '../src/setup.js';

if (existsSync('.env')) process.loadEnvFile('.env');

function need(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`${name} is not set (see packages/db/.env.example)`);
  return v;
}

await setupDatabase({
  ownerUrl: need('DATABASE_OWNER_URL'),
  passwords: {
    app_dashboard: need('APP_DASHBOARD_PASSWORD'),
    app_agent_visitor: need('APP_AGENT_VISITOR_PASSWORD'),
    app_outbox: need('APP_OUTBOX_PASSWORD'),
  },
  seedTenants:
    process.env.SEED_DEV_TENANTS === 'true'
      ? devTenants(
          need('WIDGET_DEV_ORIGINS')
            .split(',')
            .map((s) => s.trim()),
        )
      : undefined,
});
console.log(
  'database ready: roles, migrations' +
    (process.env.SEED_DEV_TENANTS === 'true' ? ', dev tenants' : ''),
);
